/**
 * Transcript adapter — harvests the agent's own sessions as usage evidence.
 *
 * The agent running the OST is the product's most active user. Every failed tool
 * call, retry, interruption, denied permission and forced clarifying question it
 * hits is *observed behavior* about where the product is hard to use — and today
 * all of it is deleted when the session ends. This adapter reads finished session
 * transcripts (Claude Code's `~/.claude/projects/<slug>/*.jsonl`), extracts those
 * signals mechanically, and emits one bounded, redacted evidence item per session.
 *
 * Deliberately mechanical: it detects friction, it does not interpret it. The
 * knowledge processes downstream (P2_map onward) do the distilling, which keeps
 * this adapter deterministic, testable and free of model calls.
 *
 * Two properties matter for the vault this writes into:
 * - strictly read-only — transcripts are never modified, moved or deleted;
 * - bounded and redacted — a capped number of short excerpts per session, with
 *   secret-shaped strings masked, because transcripts are large, noisy, and may
 *   contain material that should not be committed to a shared vault.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import type { Actor, Cursor, EvidenceItem, FetchResult, Source } from "./source.js";

/**
 * Where Claude Code keeps a project's session transcripts: `~/.claude/projects/`
 * plus the project path with every non-alphanumeric character turned into `-`.
 */
export function defaultTranscriptDir(projectDir: string): string {
  const slug = path.resolve(projectDir).replace(/[^A-Za-z0-9]/g, "-");
  return path.join(os.homedir(), ".claude", "projects", slug);
}

export type FrictionKind =
  | "tool_error"
  | "retry"
  | "interruption"
  | "permission_denied"
  | "clarifying_question";

export interface FrictionEvent {
  kind: FrictionKind;
  /** The tool involved, when the signal came from a tool call. */
  tool?: string;
  /** Short, redacted excerpt — enough context to interpret the event later. */
  detail: string;
  /** ISO timestamp of the transcript entry. */
  timestamp: string;
}

export interface TranscriptSourceOptions {
  /** Directory of `*.jsonl` session transcripts. */
  dir: string;
  /** A session is "finished" once its file has been untouched this long. */
  quietMinutes?: number;
  /** Cap on friction events reported per session (the rest are counted only). */
  maxEventsPerSession?: number;
  /** Cap on sessions harvested per fetch, newest first. */
  maxSessions?: number;
=== READER ===
/**
 * The interpretive transcript read — and the guard that keeps it honest.
 *
 * `transcript.ts` scans a session for error strings and finds `tool_error`,
 * `retry`, `clarifying_question`. Over 24 harvested sessions that channel produced
 * 82 events and not one conceptual item: the friction worth learning from is a
 * wrong framing, a rule misread, an approach abandoned — and none of those leave an
 * exit code behind. The input was never the limitation; the reader was. This module
 * reads the same file for a different thing: a model answers a small FIXED set of
 * questions about the whole session, and its answers become candidate evidence.
 *
 * **The guard is the point of this file, not the reading.** A model's account of
 * what an agent was confused about is an *assertion* about *observed* raw material,
 * and a pass that files it unmarked launders one rung into the other — the exact
 * failure this vault's believability ladder exists to catch. So every candidate
 * must carry a verbatim span from the transcript, and nothing is filed until that
 * span has been located in the very text the reader was handed
 * ({@link renderTranscriptForReading} produces both). A quote that cannot be found
 * is a paraphrase, a reconstruction or an invention, and it is dropped with a
 * reason rather than filed with a caveat.
 *
 * What that buys and what it does not: quote-traceability makes the reading
 * *checkable* by a human against the transcript. It says nothing about whether the
 * reading is any good — whether an interpretive read surfaces anything the regex
 * missed is a blind-rating question that needs a person, and it is open.
 *
 * The reader itself is INJECTED ({@link TranscriptReader}), the adapter pattern
 * this repo already uses for Slack and the web reader: the verification logic is
 * tested offline against a fake, and no model call, credential or cost is incurred
 * by anything in this file. Every session read costs money proportional to how much
 * the product is used, so the caller — not this module — decides when to spend it.
 */
import type { EvidenceItem } from "./source.js";
import { redactSecrets } from "./transcript.js";

/**
 * The fixed question set. Fixed, and not a caller-supplied prompt, because the
 * comparability of two sessions' readings depends on their having been asked the
 * same thing — and because an open prompt is how "read this transcript" becomes
 * "confirm what I already believe about this transcript".
 */
export const READING_QUESTIONS = [
  {
    id: "changed_mind",
    question: "Where did the agent change its mind, and what changed it?",
  },
  {
    id: "abandoned",
    question: "What did it try, abandon, and never come back to?",
  },
  {
    id: "repeated",
    question: "Where did it repeat itself without noticing?",
  },
  {
    id: "belief_shift",
    question: "What did it believe at the start that it did not believe at the end?",
  },
] as const;

/**
 * Friction filing — the affordance the agent uses at the point of pain.
 *
 * The transcript harvester reads friction *after the fact*, and only friction
 * that left a machine-readable trace: a failed call, a retry, an interruption.
 * The friction that costs the most — a rule the agent could not interpret, a
 * path it had to guess, an affordance it wished for — leaves no trace at all.
 * This lets the agent file one line the moment it is blocked, uncertain, or
 * forced to guess, while the context is still live.
 *
 * A filing is an ordinary inbox note: append-only, never overwriting an earlier
 * filing, picked up by `ost_ingest_inbox` like any other evidence. Notes are
 * redacted before they land, because whatever the agent was stuck on may be
 * in its hands at the time.
 *
 * Filings land in the **`friction` channel**, not in channel zero. That channel
 * exists for them and its folder is a constant inside the vault, which is what
 * `FRICTION_CHANNEL`'s own doc comment is about: once `init` began writing an
 * escaping `adapters.inbox.path`, a filing written to channel zero landed outside
 * the git working tree, so the vault's own `git add -A` stopped committing the
 * agent's record of where it got stuck.
 */
import fs from "node:fs";
import path from "node:path";
import { readConfig } from "../config/load.js";
import { FRICTION_CHANNEL, resolveChannels } from "./channels.js";
import { redactSecrets } from "./transcript.js";

/** The vocabulary the agent is told to use. Small on purpose — filing must be cheap. */
export const FRICTION_KINDS = ["blocked", "guessed", "unclear-rule", "missing-affordance", "slow"] as const;

export type FrictionFilingKind = (typeof FRICTION_KINDS)[number];

export interface FrictionFiling {
  kind: FrictionFilingKind;
  /** One line: what went wrong, in the agent's own words. */
  note: string;
  /** Optional: what it was doing, or what it wished existed. */
  context?: string;
  /** Optional: which loop/process/session filed this. */
  source?: string;
  /** ISO timestamp; defaults to now. */
  at?: string;
}

const MAX_NOTE_CHARS = 500;
const MAX_CONTEXT_CHARS = 1000;

function clean(text: string, max: number): string {
  const flat = redactSecrets(text).replace(/\s+/g, " ").trim();
  return flat.length > max ? `${flat.slice(0, max)}…` : flat;
}

function slug(note: string): string {
  return (
    note
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 48) || "friction"
  );
}

/** Pick a filename that does not exist yet — an earlier filing is never replaced. */
function uniquePath(dir: string, base: string): string {
  let candidate = path.join(dir, `${base}.md`);
  for (let n = 2; fs.existsSync(candidate); n++) {
    candidate = path.join(dir, `${base}-${n}.md`);
  }
  return candidate;
