          message: {
            role: "assistant",
            content: [{ type: "tool_use", id: "t1", name: "Bash", input: { command: "sleep 45" } }],
          },
        }),
        JSON.stringify({
          timestamp: "2026-08-05T20:00:01.000Z",
          type: "user",
          message: {
