 * Build a 10,000-node vault once, then run ost_next_work under the CPU profiler.
 * Same shape the Z3 budget test uses, so the number here is the number that gate
 * measures.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { initVault } from "/Users/tanner/dev/OST-Agent/src/runner/init.js";
