/**
 * The MCP tool-name prefix a Claude Code session will actually mint for this
 * plugin's server, derived from `.claude-plugin/plugin.json` rather than
 * hardcoded anywhere.
 *
 * Both the plugin *name* and the server key matter. A server registered
 * directly (`claude mcp add`, `.mcp.json`) is namespaced `mcp__<server>__`; one
 * delivered by a plugin — the only install path `README.md` documents — is
 * namespaced `mcp__plugin_<plugin>_<server>__`. Both names here happen to be
 * `ost-agent`, which is why the wrong form read as correct for 23 releases.
 *
 * Every grant in the repo used the direct form, so no grant matched a tool any
 * plugin session mints. Interactively that is a permission prompt; under
 * `claude -p` an ungranted call is denied rather than prompted, so the
 * unattended pass ran, had every call refused, wrote nothing, and exited `0`
 * reporting success. `docs/consuming-from-claude-code.md` records five
 * scheduled firings lost to that exact shape before it was understood.
 *
 * It lives here, in one place, imported by every test that needs it, so the
 * next rename fails one derivation instead of drifting across nine files.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

export const MCP_PREFIX: string = (() => {
  const manifest = JSON.parse(fs.readFileSync(path.join(repoRoot, ".claude-plugin", "plugin.json"), "utf8")) as {
    name?: string;
    mcpServers?: Record<string, unknown>;
  };
  const plugin = manifest.name;
  if (!plugin) throw new Error("plugin.json has no `name` — the tool namespace cannot be derived");
  const servers = Object.keys(manifest.mcpServers ?? {});
  if (servers.length !== 1) throw new Error(`expected exactly one mcpServers entry, found ${servers.length}`);
  return `mcp__plugin_${plugin}_${servers[0]}__`;
})();
